async function getBasicProfile(userId) {
  const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1e3);
  const recentFeedback = await db.select({
    completion_status: feedback.completion_status,
    score: feedback.score,
    created_at: feedback.created_at
  }).from(feedback).where(and(eq(feedback.user_id, userId), gte(feedback.created_at, since))).orderBy(desc(feedback.created_at)).limit(50);
  const completed = recentFeedback.filter((f2) => f2.completion_status === "completed").length;
  const total = recentFeedback.length || 1;
  const completionRate = completed / total;
  const scores = recentFeedback.map((f2) => f2.score).filter((s2) => typeof s2 === "number");
  const averageScore = scores.length > 0 ? scores.reduce((a, b3) => a + b3, 0) / scores.length : 5;
  let consecutiveCompletions = 0;
  let consecutiveFailures = 0;
  for (const row of recentFeedback) {
    if (row.completion_status === "completed") {
      if (consecutiveFailures > 0) break;
      consecutiveCompletions++;
    } else if (row.completion_status === "failed" || row.completion_status === "skipped") {
      if (consecutiveCompletions > 0) break;
      consecutiveFailures++;
    } else break;
  }
  const [lastOrder] = await db.select({ finished_at: orders.finished_at, updated_at: orders.updated_at }).from(orders).where(and(eq(orders.user_id, userId), inArray(orders.status, ["completed", "active", "pending"]))).orderBy(desc(orders.updated_at)).limit(1);
  const lastActiveAt = lastOrder?.finished_at ?? lastOrder?.updated_at ?? null;
  const inactiveHours = lastActiveAt ? (Date.now() - lastActiveAt.getTime()) / (60 * 60 * 1e3) : 999;
  return {
    userId,
    completionRateLast7Days: completionRate,
    averageScoreLast7Days: averageScore,
    consecutiveCompletions,
    consecutiveFailures,
    lastActiveAt,
    inactiveHours,
    burnoutRisk: null,
    procrastinationProfile: null,
    frictionTopology: null
  };
}
