async function evaluatePivotEligibility(params) {
  const [blueprint] = await db.select({ id: blueprints.id, status: blueprints.status }).from(blueprints).where(
    and(
      eq(blueprints.id, params.blueprintId),
      eq(blueprints.user_id, params.userId),
      eq(blueprints.active, true)
    )
  ).limit(1);
  if (!blueprint || blueprint.status !== BlueprintStatus.ACTIVE) {
    return { eligible: false, blockedReason: "Blueprint not active" };
  }
  const [conditionRow] = await db.select({ condition: conditions.condition }).from(conditions).where(and(eq(conditions.blueprint_id, params.blueprintId), eq(conditions.is_current, true))).limit(1);
  if (!conditionRow || conditionRow.condition === NOTHINGNESS2) {
    return {
      eligible: false,
      blockedReason: "Insufficient execution data for a directional recommendation"
    };
  }
  if (conditionRow.condition === "danger" && params.triggerType === "automatic") {
    const [{ recoveryCount }] = await db.select({ recoveryCount: sql`count(*)::int` }).from(feedback).innerJoin(orders, eq(feedback.order_id, orders.id)).where(
      and(
        eq(feedback.blueprint_id, params.blueprintId),
        eq(feedback.user_id, params.userId),
        eq(feedback.completion_status, "completed"),
        eq(feedback.validity, "valid"),
        eq(orders.task_type, "recovery")
      )
    );
    if ((recoveryCount ?? 0) === 0) {
      return {
        eligible: false,
        blockedReason: "Recovery must be attempted before a strategic review in Danger condition"
      };
    }
  }
  const [openReview] = await db.select({ id: pivotReviews.id }).from(pivotReviews).where(and(eq(pivotReviews.blueprint_id, params.blueprintId), eq(pivotReviews.status, "open"))).limit(1);
  if (openReview) {
    return { eligible: false, blockedReason: "An open pivot review already exists" };
  }
  return { eligible: true };
}
