async function interpretStructuredFeedback(input) {
  const p = input.payload;
  const finished = p.taskStates.filter((t2) => t2.state === "Finished").length;
  const total = Math.max(p.taskStates.length, 1);
  const completed = finished === total ? "COMPLETED" : finished > 0 ? "PARTIAL" : "FAILED";
  const blocked = p.taskStates.some((t2) => t2.state === "Blocked");
  const friction = p.frictionType.filter((f2) => f2 !== "nothing_blocked").join("; ");
  const interpretation = await interpretFeedback(
    {
      completed,
      score: Math.round(finished / total * 10),
      reflection: p.realitySummary,
      blocker: blocked ? friction || "Task blocked during execution" : void 0,
      confidence: 0.8
    },
    { userId: input.userId, blueprintId: input.blueprintId }
  );
  return {
    ...interpretation,
    reality: p.realitySummary ?? "User described today's execution reality.",
    tasks: p.taskStates.length,
    energy: p.emotionalState.join(", ") || "neutral",
    friction: p.frictionType.filter((f2) => f2 !== "nothing_blocked"),
    outputs: p.outputType.filter((o2) => o2 !== "no_tangible_output")
  };
}
