async function getBlueprintStructure(blueprintId) {
  const [bp] = await db.select().from(blueprints).where(eq(blueprints.id, blueprintId)).limit(1);
  if (!bp) throw new TorgimaError("NOT_FOUND", "Blueprint not found");
  const planRows = await db.select().from(plans).where(eq(plans.blueprint_id, blueprintId));
  const planIds = planRows.map((p) => p.id);
  const phaseRows = await db.select().from(phases).where(eq(phases.blueprint_id, blueprintId));
  const phaseIds = phaseRows.map((p) => p.id);
  const projectRows = phaseIds.length > 0 ? await db.select().from(projects).where(inArray(projects.phase_id, phaseIds)) : [];
  const projectIds = projectRows.map((p) => p.id);
  const actionRows = projectIds.length > 0 ? await db.select().from(actions).where(inArray(actions.project_id, projectIds)) : [];
  const actionIds = actionRows.map((a) => a.id);
  const orderRows = actionIds.length > 0 ? await db.select().from(orders).where(inArray(orders.action_id, actionIds)) : [];
  const nested = planRows.map((plan) => ({
    ...plan,
    phases: phaseRows.filter((ph) => ph.plan_id === plan.id).map((phase) => ({
      ...phase,
      projects: projectRows.filter((pr3) => pr3.phase_id === phase.id).map((project) => ({
        ...project,
        actions: actionRows.filter((a) => a.project_id === project.id).map((action) => ({
          ...action,
          orders: orderRows.filter((o2) => o2.action_id === action.id)
        }))
      }))
    }))
  }));
  return { blueprint: bp, plans: nested };
}
