async function syncCycleToMemoryGraph(blueprintId, context2, chainId) {
  const ctxNode = await memoryGraph.addNode({
    blueprintId,
    nodeType: "world",
    nodeId: `cycle-${chainId}`,
    content: {
      domain: context2.domain,
      phase: context2.phase,
      strategy: context2.strategy,
      execution: context2.execution,
      investigations: context2.investigations,
      knowledge: context2.knowledge
    },
    summary: `Cycle ${chainId}: ${context2.domain} \xB7 ${context2.phase}`,
    sourceEngine: "kernel",
    sourceEvent: chainId,
    importance: 0.85
  });
  const inv = context2.investigations;
  if (Array.isArray(inv?.items)) {
    for (const item of inv.items.slice(0, 10)) {
      const child = await memoryGraph.addNode({
        blueprintId,
        nodeType: "investigation",
        nodeId: item.id,
        content: item,
        summary: `Investigation: ${item.subject ?? item.id}`,
        sourceEngine: "investigation",
        sourceEvent: chainId
      });
      await memoryGraph.addEdge({
        blueprintId,
        fromNodeId: ctxNode.id,
        toNodeId: child.id,
        edgeType: "supports",
        strength: 0.6
      });
    }
  }
  const strategy = context2.strategy;
  if (strategy?.recommendation?.id) {
    const recNode = await memoryGraph.addNode({
      blueprintId,
      nodeType: "decision",
      nodeId: strategy.recommendation.id,
      content: strategy.recommendation,
      summary: `Decision: ${strategy.recommendation.title ?? "recommendation"}`,
      sourceEngine: "intelligence",
      sourceEvent: chainId,
      importance: 0.9
    });
    await memoryGraph.addEdge({
      blueprintId,
      fromNodeId: ctxNode.id,
      toNodeId: recNode.id,
      edgeType: "influences",
      strength: 0.8
    });
  }
}
