async function runStageWithRetry(stage, fn2, opts) {
  let lastErr;
  for (let attempt = 0; attempt <= opts.maxRetries; attempt++) {
    try {
      return await fn2();
    } catch (err) {
      lastErr = err;
      if (attempt < opts.maxRetries) {
        await new Promise((r2) => setTimeout(r2, 500 * 2 ** attempt));
      }
    }
  }
  if (opts.required) throw lastErr;
  return null;
}
